import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let m = conc.Mutex(0)
    let n = m.update(|v| v + 1)
    if n == 1 {
        io.println("one")
    } else {
        io.println("other")
    }
    return Ok(())
}
